import { KPILineChart, KPITrend, KPIValue } from '@/registry/kpi'
import type { Props as LineProps } from 'recharts/types/cartesian/Line'

import { Card, CardContent, CardDescription } from '@/components/ui/card'

interface LineChartKPIProps {
  change: string
  data: any[]
  height: number
  lines: LineProps[]
  title: string
  trend: 'up' | 'down' | 'neutral'
  value: string
}

export const LineChartKPI1 = ({
  change = '+4.2%',
  data = [
    {
      label: 'Mon',
      current: 4200,
      forecast: 3900,
      displayValues: {
        current: '4.2k visits',
        forecast: '3.9k plan',
      },
    },
    {
      label: 'Tue',
      current: 5100,
      forecast: 4700,
      displayValues: {
        current: '5.1k visits',
        forecast: '4.7k plan',
      },
    },
    {
      label: 'Wed',
      current: 4800,
      forecast: 4600,
      displayValues: {
        current: '4.8k visits',
        forecast: '4.6k plan',
      },
    },
    {
      label: 'Thu',
      current: 5600,
      forecast: 5200,
      displayValues: {
        current: '5.6k visits',
        forecast: '5.2k plan',
      },
    },
    {
      label: 'Fri',
      current: 6300,
      forecast: 6000,
      displayValues: {
        current: '6.3k visits',
        forecast: '6k plan',
      },
    },
    {
      label: 'Sat',
      current: 5400,
      forecast: 5000,
      displayValues: {
        current: '5.4k visits',
        forecast: '5k plan',
      },
    },
    {
      label: 'Sun',
      current: 4900,
      forecast: 4700,
      displayValues: {
        current: '4.9k visits',
        forecast: '4.7k plan',
      },
    },
  ],
  height = 180,
  lines = [
    {
      dataKey: 'current',
      stroke: 'var(--color-chart-1)',
    },
    {
      dataKey: 'forecast',
      stroke: 'var(--color-chart-2)',
      strokeDasharray: '4 4',
    },
  ],
  title = 'Daily visitors',
  trend = 'up',
  value = '48,230',
}: LineChartKPIProps) => {
  return (
    <Card>
      <CardContent>
        <div className='space-y-1'>
          <div className='flex items-center justify-between'>
            <CardDescription>{title}</CardDescription>
            <KPITrend value={change} trend={trend} variant='badge' />
          </div>
          <KPIValue>{value}</KPIValue>
        </div>
        <KPILineChart data={data} lines={lines} height={height} />
      </CardContent>
    </Card>
  )
}
